// Keeps the trending searches that match a watch word, once per term.
const s = $('Settings').first().json;
const watch = String(s.watchWords || '').split(',').map((w) => w.trim().toLowerCase()).filter(Boolean);
const esc = (w) => w.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const matches = (text, w) => new RegExp(`(^|[^\\p{L}\\p{N}])${esc(w)}($|[^\\p{L}\\p{N}])`, 'u').test(text);

const memory = $getWorkflowStaticData('global');
memory.sent = memory.sent || {};
const now = Date.now();
for (const [k, t] of Object.entries(memory.sent)) if (now - t > 7 * 24 * 3600 * 1000) delete memory.sent[k];

const out = [];
for (const item of $input.all()) {
  for (const t of item.json.trending_searches || []) {
    const text = [t.term, ...(t.related_terms || [])].join(' ').toLowerCase();
    const hits = watch.filter((w) => matches(text, w));
    const key = `${s.country}:${t.term}`;
    if (!hits.length || memory.sent[key]) continue;
    memory.sent[key] = now;
    out.push({ json: {
      term: t.term, volume: t.trend_volume, rank: t.rank, matches: hits,
      text: `📈 Trending on Google (${s.country}): "${t.term}" (${t.trend_volume || '?'} searches, rank ${t.rank})\n`
        + `Matches: ${hits.join(', ')}\nRelated: ${(t.related_terms || []).slice(1, 6).join(', ')}\n`
        + `https://trends.google.com/trending?geo=${s.country}`,
    } });
  }
}
return out;
